#!/usr/bin/env node

import { readFile, writeFile } from "node:fs/promises";

import { Command } from "commander";

import { format, loadConfigForFile } from "../src/index.js";

const program = new Command();

program
  .name("tidytype")
  .description("Format a JavaScript file with TidyType.")
  .argument("<file>", "JavaScript file to format")
  .option("--check", "Report whether the file is already formatted")
  .action(async (file, cliOptions) => {
    try {
      const source = await readFile(file, "utf8");
      const formatOptions = await loadConfigForFile(file);
      const formatted = format(source, formatOptions);

      if (cliOptions.check) {
        if (source === formatted) {
          console.log(`${file} is formatted.`);
        } else {
          console.error(`${file} is not formatted.`);
          process.exitCode = 1;
        }

        return;
      }

      await writeFile(file, formatted);
      console.log(`${file} formatted.`);
    } catch (error) {
      console.error(`Could not format ${file}: ${error.message}`);
      process.exitCode = 1;
    }
  });

await program.parseAsync();
